import openpyxl
# Check formatting preservation: compare style info of filled file vs input for all cells
inp=openpyxl.load_workbook('3_46121_answer_template_4279_input.xlsx', data_only=False)
out=openpyxl.load_workbook('3_46121_answer_template_4279_filled.xlsx', data_only=False)
diffs=[]
for wsname in inp.sheetnames:
    wi=inp[wsname]; wo=out[wsname]
    for row in wi.iter_rows():
        for c in row:
            o=wo[c.coordinate]
            if c.number_format != o.number_format:
                diffs.append((wsname,c.coordinate,'nf',c.number_format,o.number_format))
            if c.fill.fill_type != o.fill.fill_type:
                diffs.append((wsname,c.coordinate,'fill',c.fill.fill_type,o.fill.fill_type))
            for side in ['left','right','top','bottom']:
                b1=getattr(c.border,side); b2=getattr(o.border,side)
                if b1.style!=b2.style:
                    diffs.append((wsname,c.coordinate,'border'+side,b1.style,b2.style))
print('style diffs', len(diffs))
for d in diffs[:20]: print(d)
# also compare fonts maybe
PY
